var mostFrequentIDs = function(nums, freq) {
    class MaxHeap {
        constructor() { this.data = []; }
        push(value) {
            this.data.push(value);
            let i = this.data.length - 1;
            while (i > 0) {
                const parent = Math.floor((i - 1) / 2);
                if (this.data[parent] >= this.data[i]) break;
                [this.data[i], this.data[parent]] = [this.data[parent], this.data[i]];
                i = parent;
            }
        }
        pop() {
            if (!this.data.length) return undefined;
            const res = this.data[0];
            const last = this.data.pop();
            if (this.data.length) {
                this.data[0] = last;
                let i = 0;
                while (true) {
                    const left = 2 * i + 1;
                    const right = 2 * i + 2;
                    let largest = i;
                    if (left < this.data.length && this.data[left] > this.data[largest]) largest = left;
                    if (right < this.data.length && this.data[right] > this.data[largest]) largest = right;
                    if (largest === i) break;
                    [this.data[i], this.data[largest]] = [this.data[largest], this.data[i]];
                    i = largest;
                }
            }
            return res;
        }
        top() { return this.data[0]; }
        size() { return this.data.length; }
    }

    const idFreq = new Map();
    const freqCount = new Map();
    const heap = new MaxHeap();
    let maxFreq = Number.NEGATIVE_INFINITY;

    const incFreqCount = (value) => {
        const v = freqCount.get(value) || 0;
        freqCount.set(value, v + 1);
        if (v === 0) heap.push(value);
    };

    const decFreqCount = (value) => {
        const v = freqCount.get(value);
        if (v === undefined) return;
        if (v === 1) {
            freqCount.delete(value);
        } else {
            freqCount.set(value, v - 1);
        }
    };

    const refreshMax = () => {
        while (heap.size() > 0) {
            const t = heap.top();
            if (freqCount.has(t) && freqCount.get(t) > 0) {
                maxFreq = t;
                return;
            }
            heap.pop();
        }
        maxFreq = Number.NEGATIVE_INFINITY;
    };

    const result = [];
    for (let i = 0; i < nums.length; i++) {
        const id = nums[i];
        const delta = freq[i];

        const hasBefore = idFreq.has(id);
        const oldFreq = hasBefore ? idFreq.get(id) : 0;
        const newFreq = oldFreq + delta;

        // Update id frequency
        idFreq.set(id, newFreq);

        if (hasBefore) {
            decFreqCount(oldFreq);
        }

        incFreqCount(newFreq);

        // Update max frequency
        if (newFreq > maxFreq) {
            maxFreq = newFreq;
        } else if (hasBefore && oldFreq === maxFreq && !freqCount.has(oldFreq)) {
            refreshMax();
        }

        // When there are no entries yet (all updates could theoretically be zero), default to 0
        if (maxFreq === Number.NEGATIVE_INFINITY) {
            result.push(0);
        } else {
            result.push(maxFreq);
        }
    }

    return result;
};

